int maxDegree(std::vector<int> const& A, size_t N) {
    int highestDegree = 0;
    std::vector<int> degrees(N, 0);

    // Compute degrees in parallel, using local variables to reduce contention
    #pragma omp parallel
    {
        int localHighestDegree = 0;
