int maxDegree(std::vector<int> const& A, size_t N) {
   int highestDegree = 0;
   // Use a reduction variable to accumulate degrees across threads
   int localHighestDegree[16] = {0};

   // Parallel loop to calculate degrees in parallel, keeping track of the highest degree encountered
   #pragma omp parallel
   {
      int thread_id = omp_get_thread_num();
      int localHighest = 0;
      #pragma omp for
      for (int i = 0; i < N; i += 1) {
         int degree = 0;
         for (int j = 0; j < N; j += 1) {
            degree += A[i * N + j];
         }
         localHighest = std::max(localHighest, degree);
      }
      localHighestDegree[thread_id] = localHighest;
   }

   // Find the highest degree among all threads
   for (int i = 0; i < 16; i++) {
      highestDegree = std::max(highestDegree, localHighestDegree[i]);
   }

   return highestDegree;
}

