    // Calculate partial minimums using parallel for and reduce minimums locally
    #pragma omp parallel
    {
        float local_min = std::numeric_limits<float>::max();
        #pragma omp for
        for (size_t i = 0; i < x.size(); ++i) {
            local_min = std::min(local_min, x[i]);
            min_values[i] = local_min;
        }
    }

    // Reduction of local minimums to global minimum
    float global_min = std::numeric_limits<float>::max();
    #pragma omp parallel for reduction(min:global_min)
    for (size_t i = 0; i < x.size(); ++i) {
        global_min = std::min(global_min, min_values[i]);
    }

    // Update the vector with the final minimum values
    #pragma omp simd
    for (size_t i = 0; i < x.size(); ++i) {
        x[i] = global_min;
    }

    delete[] min_values;
}

