void mapPowersOfTwo(std::vector<int> const& x, std::vector<bool> &mask) {
    int n = x.size();
    mask.resize(n);

    // Use parallel for with reduction for better performance on larger inputs
    #pragma omp parallel
    {
        int tid = omp_get_thread_num();
        int numThreads = omp_get_num_threads();
        int chunkSize = (n + numThreads - 1) / numThreads;
        int start = tid * chunkSize;
        int end = std::min(start + chunkSize, n);

        // Local thread mask for reduction
        std::vector<bool> localMask(end - start);

        for (int i = start; i < end; i++) {
