/* Return the logical XOR reduction of the vector of bools x.
   Example:

   input: [false, false, false, true]
   output: true
*/
bool reduceLogicalXOR(std::vector<bool> const& x) {
    if (x.empty()) return false;
    bool result = x[0];
    size_t size = x.size();

    // Use sequential reduction for small vectors to avoid overhead of parallelism.
    if (size < 1000) {
        for (size_t i = 1; i < size; ++i) {
            result ^= x[i];
        }
        return result;
    }

    // Use parallel reduction for larger vectors.
    bool private_results[16]; // Assuming 16 threads for optimization
    #pragma omp parallel
    {
        int thread_id = omp_get_thread_num();
        private_results[thread_id] = x[thread_id];
        #pragma omp for
        for (size_t i = omp_get_thread_num() + 1; i < size; i += omp_get_num_threads()) {
            private_results[thread_id] ^= x[i];
        }
    }

    // Combine results from all threads
    result = private_results[0];
    for (int i = 1; i < omp_get_max_threads(); ++i) {
        result ^= private_results[i];
    }

    return result;
}

