#include <vector>
#include <cmath>
#include <complex>
#include <omp.h>

#if!defined(M_PI)
#define M_PI 3.14159265358979323846
#endif

void fft(std::vector<std::complex<double>> const& x, std::vector<std::complex<double>> &output) {
    unsigned int N = x.size();
    output.resize(N);
    std::copy(x.begin(), x.end(), output.begin());

    // DFT using a bit reversal permutation and the Cooley-Tukey algorithm
    unsigned int levels = static_cast<unsigned int>(std::log2(N));
    unsigned int size = 1;
    for (unsigned int level = 0; level < levels; ++level) {
        size <<= 1;
        unsigned int step = size >> 1;
        double angle = -2.0 * M_PI / size;
        std::complex<double> w(1.0, 0.0);
        std::complex<double> wStep(std::cos(angle), std::sin(angle));
        #pragma omp parallel for
        for (unsigned int group = 0; group < N; group += size) {
            std::complex<double> temp;
            for (unsigned int i = 0; i < step; ++i) {
                unsigned int j = group + i;
                unsigned int k = j + step;
                temp = output[j] - output[k];
                output[j] += output[k];
                output[k] = temp * w;
            }
            w *= wStep;
        }
    }

    // Decimation in time
    for (unsigned int i = 0; i < N; ++i) {
        unsigned int j = i;
        unsigned int k = N >> 1;
        while (k > 0) {
            unsigned int t = j ^ k;
            if (j < t) {
                std::swap(output[j], output[t]);
            }
            j = t;
            k >>= 1;
        }
    }
}

