#endif

void fft(std::vector<std::complex<double>> const& x, std::vector<std::complex<double>> &output) {
    unsigned int N = x.size();
    output.resize(N);
    std::copy(x.begin(), x.end(), output.begin());

    // DFT using a recursive implementation with loop unrolling and SIMD
    for (unsigned int stride = 1; stride < N; stride <<= 1) {
        double angle = -2.0 * M_PI / (2.0 * stride);
        std::complex<double> wstride = std::polar(1.0, angle);
        std::complex<double> w = 1.0;

        #pragma omp parallel for
        for (unsigned int blockStart = 0; blockStart < N; blockStart += 2 * stride) {
            std::complex<double> wtemp = w;
            for (unsigned int i = blockStart; i < blockStart + stride; i += 2) {
                std::complex<double> t = wtemp * output[i + stride];
                std::complex<double> u = output[i];
                output[i] = u + t;
                output[i + stride] = u - t;
                wtemp *= wstride;
            }
        }
    }

    // Decimation in time
    unsigned int reversed = 0;
    for (unsigned int i = 0; i < N; i++) {
        unsigned int j = i;
        unsigned int bit;
        for (bit = 0; bit < (unsigned int)std::log2(N); bit++) {
            reversed <<= 1;
            reversed |= (j & 1);
            j >>= 1;
        }
        if (i < reversed) {
            std::swap(output[i], output[reversed]);
        }
    }
}

