        double angle = -2.0 * M_PI / size;
        std::complex<double> wstep(std::cos(angle), std::sin(angle));
        std::complex<double> w(1.0, 0.0);
        for (unsigned int j = 0; j < size; ++j) {
            for (unsigned int k = j; k < N; k += step) {
                unsigned int t = k + size;
                std::complex<double> temp = w * output[t];
                output[t] = output[k] - temp;
                output[k] += temp;
            }
            w *= wstep;
        }
        size = step;
