void fft(std::vector<std::complex<double>> &x) {
    int n = x.size();
    int levels = 0;
    while ((1 << levels) < n) ++levels;

    // Rearrange the elements to bit-reversed order
    for (int i = 0; i < n; ++i) {
        int rev = 0;
        for (int j = 0; j < levels; ++j) {
            rev = (rev << 1) | (i & (1 << j))? 1 : 0;
