    }

    // In-place Cooley-Tukey FFT
    for (size_t s = 1; s < N; s *= 2) {
        const double angle = -2.0 * M_PI / (2.0 * s);
        std::complex<double> w(cos(angle), sin(angle));
        for (size_t i = 0; i < N; i += 2 * s) {
