    }

    auto getDist = [](double const& a, double const& b) {
        return std::abs(b-a);
    };

    double minDist = std::numeric_limits<double>::max();
    for (size_t i = 0; i < x.size() - 1; i++) {
        for (size_t j = i + 1; j < x.size(); j++) {
            const double dist = getDist(x[i], x[j]);
            if (dist < minDist) {
                minDist = dist;
            }
        }
    }

    return minDist;
}


