void convexHull(std::vector<Point> const& points, std::vector<Point> &hull) {
    // The polygon needs to have at least three points
    if (points.size() < 3)   {
        hull = points;
        return;
    }

    // Sort points based on their x-coordinates, and then y-coordinates
    std::vector<Point> pointsSorted = points;
    std::sort(pointsSorted.begin(), pointsSorted.end(), [](Point const& a, Point const& b) {
        return a.x < b.x || (a.x == b.x && a.y < b.y);
    });

    // Helper function to calculate the cross product of two vectors (a -> b) x (a -> c)
    auto CrossProduct = [](Point const& a, Point const& b, Point const& c) {
        return (c.x - a.x) * (b.y - a.y) - (c.y - a.y) * (b.x - a.x);
    };

    // Helper function to build the convex hull
    auto BuildHull = [&](std::vector<Point> const& pointsSorted, std::vector<Point>& hull) {
        hull.clear();
        hull.reserve(pointsSorted.size());

        for (size_t i = 0; i < pointsSorted.size(); ++i) {
            while (hull.size() >= 2 && CrossProduct(hull[hull.size() - 2], hull.back(), pointsSorted[i]) <= 0) {
                hull.pop_back();
            }
            hull.push_back(pointsSorted[i]);
        }

        // Reverse the lower hull to get the correct order
        std::reverse(hull.begin(), hull.end());
    };

    std::vector<Point> upperHull;
    std::vector<Point> lowerHull;

    // Build the upper hull
    BuildHull(pointsSorted, upperHull);

    // Build the lower hull in a single pass by considering the points in reverse order
    for (int i = pointsSorted.size() - 2; i >= 0; --i) {
        while (lowerHull.size() >= 2 && CrossProduct(lowerHull[lowerHull.size() - 2], lowerHull.back(), pointsSorted[i]) <= 0) {
            lowerHull.pop_back();
        }
        lowerHull.push_back(pointsSorted[i]);
    }

    // Combine the upper and lower hulls
    hull.reserve(upperHull.size() + lowerHull.size());
    hull.insert(hull.end(), upperHull.begin(), upperHull.end());

    // Remove the first point of the lower hull (it's the same as the last point of the upper hull)
    lowerHull.erase(lowerHull.begin());
    hull.insert(hull.end(), lowerHull.begin(), lowerHull.end());
}

