void convolveKernel(std::vector<int> const& imageIn, std::vector<int> &imageOut, size_t N) {
    // Create a threshold array to avoid multiple comparisons in the inner loop
    int threshold[9];
    for (int i = 0; i < 9; ++i) {
        threshold[i] = edgeKernel[i / 3][i % 3] * (i < 4? -1 : 8);
    }

    #pragma omp parallel for
    for (size_t i = 0; i < N; i++) {
        for (size_t j = 0; j < N; j++){
            int sum = 0;
            // Loop unrolling for better performance
            for (int k = -1; k < 2; k++) {
                for (int l = -1; l < 2; l += 2) {
                    int idx = (k + 1) * 3 + (l + 1);
                    int x = i + k;
                    int y = j + l;
                    int val = (x >= 0 && x < N && y >= 0 && y < N)? imageIn[x * N + y] : 0;
                    sum += val * threshold[idx];
                    if (l < 0) {
                        y = j + l + 1;
                        val = (x >= 0 && x < N && y >= 0 && y < N)? imageIn[x * N + y] : 0;
                        sum += val * threshold[idx];
                    }
                }
            }
            if (sum < 0) {
                imageOut[i * N + j] = 0;
            } else if (sum > 255) {
                imageOut[i * N + j] = 255;
            } else {
                imageOut[i * N + j] = sum;
            }
        }
    }
}

