#pragma once
#include <vector>
#include <omp.h>

void gameOfLife(std::vector<int> const& input, std::vector<int> &output, size_t N) {
    // Create a temporary output array to store the new state of each cell
    std::vector<int> temp_output(N * N);

    // Use OpenMP for parallel processing
    #pragma omp parallel for
    for (size_t i = 0; i < N; i++) {
        for (size_t j = 0; j < N; j++) {
            int sum = 0;
            int index = i * N + j;

            // Check the cell to the left
            if (j > 0) {
                sum += input[index - 1];
            }
            // Check the cell to the right
            if (j < N - 1) {
                sum += input[index + 1];
            }
            // Check the cell above
            if (i > 0) {
                sum += input[index - N];
            }
            // Check the cell below
            if (i < N - 1) {
                sum += input[index + N];
            }
            // Check the top-left diagonal
            if (i > 0 && j > 0) {
                sum += input[index - N - 1];
            }
            // Check the top-right diagonal
            if (i > 0 && j < N - 1) {
                sum += input[index - N + 1];
            }
            // Check the bottom-left diagonal
            if (i < N - 1 && j > 0) {
                sum += input[index + N - 1];
            }
            // Check the bottom-right diagonal
            if (i < N - 1 && j < N - 1) {
                sum += input[index + N + 1];
            }

            // Apply the rules of the Game of Life
            int current_state = input[index];
            if (current_state == 1) {
                if (sum < 2 || sum > 3) {
                    temp_output[index] = 0; // Loneliness or overpopulation
                } else {
                    temp_output[index] = 1; // Remains alive
                }
            } else {
                if (sum == 3) {
                    temp_output[index] = 1; // Reproduction
                } else {
                    temp_output[index] = 0; // Stasis
                }
            }
        }
    }

    // Copy the temporary output to the main output array
    output = temp_output;
}

