void axpy(double alpha, std::vector<double> const& x, std::vector<double> const& y, std::vector<double> &z) {
    size_t size = x.size();
    size_t i = 0;
    // Process 4 elements at a time using SIMD instructions
    for (; i + 4 <= size; i += 4) {
        __m256d x_vec = _mm256_loadu_pd(&x[i]);
        __m256d y_vec = _mm256_loadu_pd(&y[i]);
        __m256d alpha_vec = _mm256_set1_pd(alpha);
        __m256d z_vec = _mm256_fmadd_pd(alpha_vec, x_vec, y_vec);
        _mm256_storeu_pd(&z[i], z_vec);
    }
    // Handle remaining elements
    for (; i < size; i++) {
        z[i] = alpha * x[i] + y[i];
    }
}

