void gemm(std::vector<double> const& A, std::vector<double> const& B, std::vector<double> &C, size_t M, size_t K, size_t N) {
    // Parallelize outer loop to use multiple threads for rows.
    #pragma omp parallel for
    for (size_t i = 0; i < M; i += 1) {
        double* c_row = &C[i * N];
        const double* a_row = &A[i * K];

        // Loop unrolling for better performance
        for (size_t k = 0; k < K; k += 4) {
            const double a0 = a_row[k];
            const double a1 = k + 1 < K? a_row[k + 1] : 0.0;
            const double a2 = k + 2 < K? a_row[k + 2] : 0.0;
            const double a3 = k + 3 < K? a_row[k + 3] : 0.0;

            // Load four columns of B at once
            const double* b_col0 = &B[k * N];
            const double* b_col1 = &B[(k + 1) * N];
            const double* b_col2 = &B[(k + 2) * N];
            const double* b_col3 = &B[(k + 3) * N];

            // Compute the dot product for four columns
            for (size_t j = 0; j < N; j += 1) {
                c_row[j] += a0 * b_col0[j] + a1 * b_col1[j] + a2 * b_col2[j] + a3 * b_col3[j];
            }
        }
    }
}

