#pragma once
#include <vector>
#include <immintrin.h>

void gemv(std::vector<double> const& A, std::vector<double> const& x, std::vector<double> &y, size_t M, size_t N) {
    for (size_t i = 0; i < M; i++) {
        double sum = 0.0;
        size_t j = 0;
        // Process 4 elements at a time using SIMD instructions
        for (; j + 4 <= N; j += 4) {
            __m256d a_vec = _mm256_loadu_pd(&A[i * N + j]);
            __m256d x_vec = _mm256_loadu_pd(&x[j]);
            __m256d prod = _mm256_mul_pd(a_vec, x_vec);
            __m256d sum_vec = _mm256_loadu_pd(&sum);
            sum_vec = _mm256_add_pd(sum_vec, prod);
            _mm256_storeu_pd(&sum, sum_vec);
        }
        // Horizontal addition to get the final sum
        for (int k = 0; k < 4; ++k) {
            sum += ((double*)&sum)[k];
        }
        // Process remaining elements
        for (; j < N; j++) {
            sum += A[i * N + j] * x[j];
        }
        y[i] = sum;
    }
}

