    #pragma omp parallel
    {
        // Local temporary storage for each thread's contributions to y
        std::vector<double> local_y(M, 0.0);

        #pragma omp for
        for (size_t i = 0; i < M; i++) {
            for (size_t j = 0; j < N; j++) {
                local_y[i] += A[i * N + j] * x[j];
