void ranks(std::vector<float> const& x, std::vector<size_t> &ranks_) {
    std::vector<size_t> indices(x.size());
    std::iota(indices.begin(), indices.end(), 0);

    // Sorting indices directly, preserving original order for equal elements
    std::sort(indices.begin(), indices.end(), [&x](size_t i1, size_t i2) {
        return x[i1] < x[i2] || (x[i1] == x[i2] && i1 < i2);
    });

    // Fill ranks in a single pass
    for (size_t i = 0; i < indices.size(); ++i) {
        ranks_[indices[i]] = i;
    }
}

// Parallel implementation for larger sizes
void ranks_parallel(std::vector<float> const& x, std::vector<size_t> &ranks_) {
    std::vector<size_t> indices(x.size());
    std::iota(indices.begin(), indices.end(), 0);

    // Sorting indices directly, preserving original order for equal elements
    std::sort(indices.begin(), indices.end(), [&x](size_t i1, size_t i2) {
        return x[i1] < x[i2] || (x[i1] == x[i2] && i1 < i2);
    });

    // Fill ranks in parallel, handling small partitions efficiently
    #pragma omp parallel
    {
        int thread_id = omp_get_thread_num();
        int num_threads = omp_get_num_threads();
        int chunk_size = indices.size() / num_threads;
