/**
 * @brief Sorts a vector of complex numbers based on their magnitude.
 *
 * This function takes a reference to a vector of complex numbers as input,
 * and sorts the vector in place to place the numbers in ascending order
 * based on their magnitude. The sorting algorithm used is the standard
 * library's sort function, which is optimized to use an efficient
 * introsort algorithm.
 *
 * @param x A reference to a vector of complex numbers to be sorted.
 */
void sortComplexByMagnitude(std::vector<std::complex<double>> &x) {
    std::sort(x.begin(), x.end(), [](const std::complex<double> &a, const std::complex<double> &b) {
        return std::abs(a) < std::abs(b);
    });
}

/**
 * @brief Optimized sorting function for vectors of complex numbers.
 *
 * This function implements a hybrid sorting algorithm that combines
 * parallel execution with the standard library's sort function for
 * small vectors. The threshold for switching between parallel and
 * sequential execution is set to 1000 elements.
 *
 * @param x A reference to a vector of complex numbers to be sorted.
 */
void sortComplexByMagnitudeOptimized(std::vector<std::complex<double>> &x) {
    const size_t size = x.size();
    if (size < 1000) {
        sortComplexByMagnitude(x);
        return;
    }

