    #pragma omp parallel
    {
        // Each thread sorts a segment of the vector
        #pragma omp for
        for (size_t i = 0; i < size; i += omp_get_num_threads()) {
            size_t threadId = omp_get_thread_num();
            size_t segmentSize = size / omp_get_num_threads();
            size_t start = i + threadId * segmentSize;
            size_t end = (threadId == omp_get_num_threads() - 1)? size : start + segmentSize;
            std::sort(x.begin() + start, x.begin() + end, [](const std::complex<double> &a, const std::complex<double> &b) {
