        // Sort the collected non-zero elements
        std::sort(nonZeroElements.begin(), nonZeroElements.end());

        // Replace non-zero elements in the original vector
        size_t index = 0;
        for (int i = 0; i < x.size(); i++) {
            if (x[i]!= 0) {
                x[i] = nonZeroElements[index++];
            }
        }
    }
