 * @brief Find the k-th smallest element of the vector x.
 *
 * This function first sorts the vector x in ascending order using an optimized sorting algorithm,
 * then returns the element at index k-1, which is the k-th smallest element.
 *
 * @param x A constant reference to a vector of integers.
 * @param k An integer representing the index (starting from 1) of the element to be found.
 * @return The k-th smallest element of the vector x.
 */
int findKthSmallest(std::vector<int> const& x, int k) {
    // Create a copy of the vector to avoid modifying the original
    std::vector<int> x_copy = x;
    const size_t size = x_copy.size();

    // Use optimized sorting for small vectors
    if (size < 16) {
        std::sort(x_copy.begin(), x_copy.end());
        return x_copy[k - 1];
    }

    // Use a hybrid approach for larger vectors
    int threshold = 32;
    while (size > threshold) {
        // Choose a pivot and partition the array
        int pivot = x_copy[size / 2];
        std::swap(x_copy[0], x_copy[size / 2]); // Move pivot to beginning
        int left = 1;
        int right = size - 1;
        while (left <= right) {
            if (x_copy[left] >= pivot && x_copy[right] < pivot) {
                std::swap(x_copy[left], x_copy[right]);
                ++left;
                --right;
            }
            if (x_copy[left] < pivot) {
                ++left;
            }
            if (x_copy[right] >= pivot) {
                --right;
            }
        }
        std::swap(x_copy[0], x_copy[right]); // Move pivot to its final place

        // Recursively handle the subarrays
