    std::vector<int> x_copy = x;
    const size_t size = x_copy.size();

    // Use optimized sorting for small vectors
    if (size < 16) {
        std::sort(x_copy.begin(), x_copy.end());
        return x_copy[k - 1];
    }

    // Use a hybrid approach for larger vectors
    // Use insertion sort for small partitions, then switch to introselect for larger ones
    const size_t threshold = 16;
    #pragma omp parallel
    {
        #pragma omp single
        {
            // Divide the vector into two parts: [0, cut) and [cut, size)
            size_t cut = size / 2;
            // Use introselect for the first half
            std::nth_element(x_copy.begin(), x_copy.begin() + cut - 1, x_copy.begin() + size, std::less<int>());
