            size_t i = cut;
            while (i < size && x_copy[i] < pivot) {
                ++i;
            }
            size_t storeIndex = i;
            while (i < size) {
                if (x_copy[i] < pivot) {
                    std::swap(x_copy[storeIndex], x_copy[i]);
                    ++storeIndex;
                }
                ++i;
            }

